// ResourceServiceHandler is an implementation of the akp.cluster.v2.ResourceService service.
type ResourceServiceHandler interface {
	// GetResource is an object, or the view of it the request asks for.
	GetResource(context.Context, *connect.Request[v2.GetResourceRequest]) (*connect.Response[v2.GetResourceResponse], error)
	// ListResources lists the objects of a resource, in a namespace or across the cluster. A whole
	// list is sorted: feature sets by whether they require features, then title, anything else
	// newest first, then by name. A page keeps the API server's order.
	ListResources(context.Context, *connect.Request[v2.ListResourcesRequest]) (*connect.Response[v2.ListResourcesResponse], error)
	// CreateResource creates an object.
	CreateResource(context.Context, *connect.Request[v2.CreateResourceRequest]) (*connect.Response[v2.CreateResourceResponse], error)
	// UpdateResource replaces an object.
	UpdateResource(context.Context, *connect.Request[v2.UpdateResourceRequest]) (*connect.Response[v2.UpdateResourceResponse], error)
	// PatchResource patches an object.
	PatchResource(context.Context, *connect.Request[v2.PatchResourceRequest]) (*connect.Response[v2.PatchResourceResponse], error)
	// PatchResourceStatus patches the status subresource of an object.
	PatchResourceStatus(context.Context, *connect.Request[v2.PatchResourceStatusRequest]) (*connect.Response[v2.PatchResourceStatusResponse], error)
	// DeleteResource deletes an object.
	DeleteResource(context.Context, *connect.Request[v2.DeleteResourceRequest]) (*connect.Response[v2.DeleteResourceResponse], error)
	// DeleteResources deletes the objects of a resource a selector selects.
	DeleteResources(context.Context, *connect.Request[v2.DeleteResourcesRequest]) (*connect.Response[v2.DeleteResourcesResponse], error)
	// BatchDeleteResources deletes objects of any resources, and answers the ones it could not.
	BatchDeleteResources(context.Context, *connect.Request[v2.BatchDeleteResourcesRequest]) (*connect.Response[v2.BatchDeleteResourcesResponse], error)
	// ListResourceEvents lists the events of an object.
	ListResourceEvents(context.Context, *connect.Request[v2.ListResourceEventsRequest]) (*connect.Response[v2.ListResourceEventsResponse], error)
	// GetResourceController is the workload that controls an object, or the object itself.
	GetResourceController(context.Context, *connect.Request[v2.GetResourceControllerRequest]) (*connect.Response[v2.GetResourceControllerResponse], error)
	// GetScale is the scale subresource of a namespaced object.
	GetScale(context.Context, *connect.Request[v2.GetScaleRequest]) (*connect.Response[v2.GetScaleResponse], error)
	// UpdateScale sets the replicas of a namespaced object through its scale subresource.
	UpdateScale(context.Context, *connect.Request[v2.UpdateScaleRequest]) (*connect.Response[v2.UpdateScaleResponse], error)
	// ListHorizontalPodAutoscalers lists the horizontal pod autoscalers that scale an object.
	ListHorizontalPodAutoscalers(context.Context, *connect.Request[v2.ListHorizontalPodAutoscalersRequest]) (*connect.Response[v2.ListHorizontalPodAutoscalersResponse], error)
	// ListGroupVersionObjects lists the names of every object of an API group version, by kind.
	ListGroupVersionObjects(context.Context, *connect.Request[v2.ListGroupVersionObjectsRequest]) (*connect.Response[v2.ListGroupVersionObjectsResponse], error)
	// GetNodeMetrics is a node's capacity, allocatable resources and usage. A cluster without the
	// metrics API has no usage.
	GetNodeMetrics(context.Context, *connect.Request[v2.GetNodeMetricsRequest]) (*connect.Response[v2.GetNodeMetricsResponse], error)
	// GetPodMetrics is a pod's requests, limits and usage, by container and in total. A cluster
	// without the metrics API has no usage.
	GetPodMetrics(context.Context, *connect.Request[v2.GetPodMetricsRequest]) (*connect.Response[v2.GetPodMetricsResponse], error)
	// CreateSelfSubjectAccessReviews asks the cluster, all at once, whether the caller may do what
	// each review describes.
	CreateSelfSubjectAccessReviews(context.Context, *connect.Request[v2.CreateSelfSubjectAccessReviewsRequest]) (*connect.Response[v2.CreateSelfSubjectAccessReviewsResponse], error)
	// GetAvailableMenu is a meta.k8s.appscode.com menu, as far as the caller may use it.
	GetAvailableMenu(context.Context, *connect.Request[v2.GetAvailableMenuRequest]) (*connect.Response[v2.GetAvailableMenuResponse], error)
	// RenderResource creates one of the virtual objects that render a view of the cluster (see
	// RenderResourceRequest) and answers it.
	RenderResource(context.Context, *connect.Request[v2.RenderResourceRequest]) (*connect.Response[v2.RenderResourceResponse], error)
	// GetDatabaseConfiguration is a ui.kubedb.com DatabaseConfiguration, read with get options of
	// its API server's own.
	GetDatabaseConfiguration(context.Context, *connect.Request[v2.GetDatabaseConfigurationRequest]) (*connect.Response[v2.GetDatabaseConfigurationResponse], error)
	// CreateResourceFromManifest creates the object of a YAML or JSON manifest of any kind the
	// cluster serves, in its namespace (default if it names none) for a namespaced kind.
	CreateResourceFromManifest(context.Context, *connect.Request[v2.CreateResourceFromManifestRequest]) (*connect.Response[v2.CreateResourceFromManifestResponse], error)
	// GetResourceHistory is the recorded history of the resources of a cluster. Unavailable where
	// AKP keeps no history.
	GetResourceHistory(context.Context, *connect.Request[v2.GetResourceHistoryRequest]) (*connect.Response[v2.GetResourceHistoryResponse], error)
	// StreamPodLogs follows the log of a container, from its last lines, until the caller ends the
	// stream or the container's log ends. Each message is one line.
	StreamPodLogs(context.Context, *connect.Request[v2.StreamPodLogsRequest], *connect.ServerStream[v2.StreamPodLogsResponse]) error
}

